package com.muxigame.city;
import java.util.*;
import net.minecraft.server.MinecraftServer;

/** Immediate finite service at the existing baker's work settlement; no deposits or order queues. */
public final class CityBakeService {
 static int fee(CityTrade t){return t.state.config.bakeFee;}
 static void earn(MinecraftServer s,CityTrade.Business b,long now){long segment=Math.floorDiv(now,3000);if(b.bakeSegment==segment)return;b.bakeSegment=segment;var p=RuralSettlement.get(s).state.people.get(b.worker);b.outputCredit=Math.min(20,b.outputCredit+20*RuralRules.efficiency(p.trainedHours)*FamilyLivelihood.workFactor(s,p)*CityWorks.workerEfficiency(s,CityData.get(s).require(b.city),p.id)/10000.0);}
 static int wanted(MinecraftServer s,RuralRules.Family family){var d=RuralSettlement.get(s);var t=CityTrade.get(s);var stores=d.stocks(family.id);int raw=RuralRules.count(stores,false);if(raw==0||RuralRules.members(family,d.state.people).isEmpty())return 0;int ready=RuralCooking.ready(stores);var home=t.state.households.get(family.id);int own=home!=null&&FamilyLivelihood.processor(s,family)?Math.min(raw,(int)home.credit):0;return Math.min(Math.max(0,raw-own),Math.max(0,RuralRules.demand(family,d.state.people)-ready-own));}
 static boolean preferred(MinecraftServer s,RuralRules.Family f){var t=CityTrade.get(s);long now=RuralSettlement.get(s).state.simulationTicks;return t.stock(s,f.city,1)==0||t.quote(s,f.city,1,now)>t.quote(s,f.city,0,now)+fee(t)||RuralRules.capacity(RuralSettlement.get(s).stocks(f.id))==0&&wanted(s,f)>0;}
 // Retail demand excludes food already covered by own ingredients and affordable baking service.
 static int retailDemand(MinecraftServer s,UUID city){var d=RuralSettlement.get(s);var t=CityTrade.get(s);int wanted=CityRelief.forecast(s,city),quote=t.quote(s,city,1,d.state.simulationTicks);for(var f:d.state.families.values())if(f.city.equals(city)){var stores=d.stocks(f.id);int need=Math.max(0,CityTrade.mealTarget(f,d)-RuralCooking.ready(stores)),raw=RuralRules.count(stores,false);var home=t.state.households.get(f.id);if(FamilyLivelihood.processor(s,f)&&home!=null&&!home.preferPrepared)need=Math.max(0,need-raw);else if(preferred(s,f))need=Math.max(0,need-(int)Math.min(raw,t.familyMoney(s,f)/fee(t)));wanted+=(int)Math.min(need,t.familyMoney(s,f)/quote);}int existing=t.stock(s,city,1)+t.state.businesses.values().stream().filter(b->b.city.equals(city)&&b.kind.equals("baker")).mapToInt(b->b.stock[1].count).sum();return Math.max(0,wanted-existing);}
 static int serve(MinecraftServer s,CityTrade.Business b){var t=CityTrade.get(s);if(!b.kind.equals("baker")||!t.usable(s,b)||!WorkHours.active(s,CityData.get(s).require(b.city),b.worker))return 0;var d=RuralSettlement.get(s);var families=new ArrayList<>(d.state.families.values().stream().filter(f->f.city.equals(b.city)).toList());if(families.isEmpty())return 0;Collections.rotate(families,-(int)Math.floorMod(Math.floorDiv(d.state.simulationTicks,3000),families.size()));int done=0;
  for(var f:families){if(b.breadRemaining<=0||b.outputCredit<1)break;if(!preferred(s,f))continue;int n=(int)Math.min(Math.min(wanted(s,f),b.breadRemaining),Math.min((int)b.outputCredit,t.familyMoney(s,f)/fee(t)));if(n<=0)continue;long payment=(long)n*fee(t);var e=CityEconomy.get(s);if(e.balance(b.account)>CityEconomy.LIMIT-payment)continue;
   var stores=d.stocks(f.id);var draft=stores.stream().map(CityJointTrade::copy).toList();var part=FoodMoves.remove(draft,0,n);if(part.count()!=n||FoodMoves.add(draft,1,n,0)!=n)continue;
   if(!pay(s,f,b.account,payment))continue;CityJointTrade.commit(stores,draft);b.outputCredit-=n;b.breadRemaining-=n;b.bakeUnits+=n;b.bakeOrders++;boolean own=f.members.contains(b.owner);if(own)b.bakeOwnUnits+=n;else{b.bakeFees+=payment;b.sales+=payment;t.profit(s,b,(int)payment,0);}d.state.breadProduced+=n;done+=n;b.status="代烤：实际小麦换面包，收取加工费";
  }if(done>0){t.setDirty();d.setDirty();}return done;
 }
 static boolean pay(MinecraftServer s,RuralRules.Family f,String recipient,long amount){var t=CityTrade.get(s);var e=CityEconomy.get(s);if(t.familyMoney(s,f)<amount||e.balance(recipient)>CityEconomy.LIMIT-amount)return false;long left=amount;for(var id:f.members){long n=Math.min(left,e.balance(CityEconomy.person(id)));if(n>0)CityEconomy.require(CityTrade.pay(s,CityEconomy.person(id),recipient,n,"BAKE_SERVICE"),"代烤付款预检失败");left-=n;if(left==0)break;}return left==0;}
}
